const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),wrap=document.getElementById('canvasWrap');const VW=960,VH=540,T=32,WORLD=125,ROWS=32;let sx=1,sy=1,dpr=1;
function fit(){let r=wrap.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=r.width*dpr;canvas.height=r.height*dpr;sx=canvas.width/VW;sy=canvas.height/VH;ctx.setTransform(sx,0,0,sy,0,0)}new ResizeObserver(fit).observe(wrap);fit();
const tileDefs={1:{name:'earth',color:'#9b7557',hard:1},2:{name:'grass',color:'#79a96f',hard:1},3:{name:'stone',color:'#75848b',hard:2},4:{name:'wood',color:'#946444',hard:2},5:{name:'leaves',color:'#69a77b',hard:1},6:{name:'ore',color:'#5d9fa0',hard:3},7:{name:'mushroom',color:'#d47c91',hard:1},8:{name:'platform',color:'#bd9165',hard:1}};
let map=Array.from({length:ROWS},()=>Array(WORLD).fill(0)),surface=[],trees=[],oreNodes=[],spores=[],particles=[],enemies=[],drops=[],decor=[],day=0,cam=0,started=false,paused=false,selected='pick',mouse={x:0,y:0,down:false},keys={},last=0,toastTimer=0;
let p={x:150,y:100,w:22,h:30,vx:0,vy:0,ground:false,face:1,hp:100,mana:40,level:1,xp:0,wood:0,ore:0,spore:0,blocks:12,coins:0,damage:1,invuln:0,attack:0};let quest=0,hasBlade=false,potion=0,boss=null,bossUnlocked=false,portalX=2910,toastEl=document.getElementById('toast');
function rng(n){let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)}
for(let x=0;x<WORLD;x++){let h=12+Math.round(Math.sin(x*.15)*1.25+Math.sin(x*.047)*2.1+Math.sin(x*.35)*.45);surface[x]=Math.max(9,Math.min(17,h));for(let y=h;y<ROWS;y++)map[y][x]=y===h?2:(y<h+4?1:3);}
// Floating shelves, ore pockets, old shrine and a route to the sky
for(let x=8;x<13;x++)map[8][x]=8;for(let x=23;x<29;x++)map[6][x]=8;for(let x=39;x<44;x++)map[9][x]=8;for(let x=58;x<64;x++)map[7][x]=8;for(let x=77;x<82;x++)map[10][x]=8;for(let x=96;x<103;x++)map[6][x]=8;
for(let x=0;x<WORLD;x++)for(let y=surface[x]+5;y<ROWS-2;y++)if(rng(x*41+y*3)>.84&&y>surface[x]+7)map[y][x]=0;
for(let x=5;x<WORLD-5;x++){if(rng(x)>.83&&x>2){let y=surface[x]-1,ht=3+Math.floor(rng(x*3)*3);trees.push({x,y,ht});for(let i=1;i<=ht;i++)map[y-i][x]=4;for(let yy=y-ht-2;yy<=y-ht+1;yy++)for(let xx=x-2;xx<=x+2;xx++)if(yy>=0&&rng(xx*7+yy*17+x)>.17&&!map[yy][xx])map[yy][xx]=5;}}
for(let x=0;x<WORLD;x++)for(let y=surface[x]+3;y<ROWS-2;y++)if(map[y][x]===3&&rng(x*9+y*31)>.977){map[y][x]=6;oreNodes.push({x,y})}
for(let i=0;i<45;i++){let x=Math.floor(rng(i*5+4)*WORLD),y=Math.max(2,surface[x]-2-Math.floor(rng(i*13)*4));decor.push({x,y,type:i%3,phase:rng(i*17)*6.28})}
let mira={x:225,y:(surface[7]-1)*T-30},mushroom={x:2100,y:(surface[65]-1)*T-22};
function say(text){toastEl.textContent=text;toastEl.classList.add('show');toastTimer=2.1}
function sync(){let xpNeed=30+(p.level-1)*25;document.getElementById('levelText').textContent=String(p.level).padStart(2,'0');document.getElementById('xpText').textContent=`${p.xp} / ${xpNeed} XP`;document.getElementById('xpFill').style.width=Math.min(100,p.xp/xpNeed*100)+'%';document.getElementById('hpText').textContent=`${Math.ceil(p.hp)} / 100`;document.getElementById('hpFill').style.width=Math.max(0,p.hp)+'%';document.getElementById('manaText').textContent=`${Math.floor(p.mana)} / 40`;document.getElementById('manaFill').style.width=p.mana/40*100+'%';document.getElementById('blockCount').textContent=p.blocks;document.getElementById('coinText').textContent=p.coins;document.getElementById('woodCost').textContent=`🪵 ${p.wood} / 3`;document.getElementById('sporeCost').textContent=`✿ ${p.spore} / 2`;document.getElementById('oreCost').textContent=`◆ ${p.ore} / 3`;document.getElementById('craftPlatform').disabled=p.wood<3;document.getElementById('craftPotion').disabled=p.spore<2;document.getElementById('craftBlade').disabled=p.ore<3||p.wood<2;document.querySelector('[data-path="warrior"]').classList.toggle('locked',!hasBlade);document.querySelector('[data-path="warrior"] small').textContent=hasBlade?'Unlocked · close combat':'Needs Rootbound blade';}
function questSet(){let n=document.getElementById('questName'),s=document.getElementById('questStatus'),t=document.getElementById('questText'),fill=document.getElementById('questFill'),count=document.getElementById('questCount');if(quest===0){n.textContent='A Place to Begin';s.textContent='TALK TO MIRA THE WAYFINDER';t.textContent='Find Mira near the old lantern and ask about the Wildroots.';fill.style.width='0%';count.textContent='0 / 1 OBJECTIVE'}else if(quest===1){n.textContent='A Home in the Wilds';s.textContent='GATHER 3 WILDWOOD';t.textContent='Mira thinks a little shelter is a fine start. Chop trees with your pickaxe.';fill.style.width=Math.min(100,p.wood/3*100)+'%';count.textContent=`${Math.min(3,p.wood)} / 3 WILDWOOD`}else if(quest===2){n.textContent='The Rootbound Blade';s.textContent='CRAFT A ROOTBOUND BLADE';t.textContent='Mine teal ore below the surface, then craft your first class weapon.';fill.style.width=hasBlade?'100%':Math.min(90,p.ore/3*90)+'%';count.textContent=hasBlade?'1 / 1 BLADE FORGED':`${p.ore} / 3 TEAL ORE`}else{n.textContent='An Ancient Heart';s.textContent='FIND THE ELDER MUSHMOTHER';t.textContent='Walk east to the old root shrine. Press Q to unleash a blade storm.';fill.style.width=boss?'55%':'15%';count.textContent=boss?'WORLD ROOT AWAKENED':'FOLLOW THE ROOTLIGHT EAST'}}
function levelUp(){let need=30+(p.level-1)*25;if(p.xp>=need){p.xp-=need;p.level++;p.hp=100;p.mana=40;say(`LEVEL ${p.level} · YOUR SPIRIT GROWS`);if(p.level===3&&!bossUnlocked){bossUnlocked=true;say('THE OLD ROOT SHRINE STIRS TO LIFE')}}}
function gainXP(n){p.xp+=n;levelUp();sync();questSet()}
function start(){if(started)return;started=true;document.getElementById('cover').classList.add('hidden');p.x=160;p.y=(surface[5]-1)*T-p.h;cam=0;last=performance.now();sync();questSet();requestAnimationFrame(loop);say('WELCOME TO THE WILDROOTS')}
document.getElementById('beginBtn').onclick=start;

