function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
function solid(id){return id!==0&&id!==5}
function collides(x,y){let l=Math.floor(x/T),r=Math.floor((x+p.w-1)/T),top=Math.floor(y/T),bot=Math.floor((y+p.h-1)/T);for(let ty=top;ty<=bot;ty++)for(let tx=l;tx<=r;tx++)if(solid(map[ty]?.[tx]||0))return true;return false}
function placeBlock(){if(p.blocks<=0){say('NO WILDWOOD PLATFORMS LEFT');return}let wx=Math.floor((mouse.x+cam)/T),wy=Math.floor((mouse.y+(p.y-270))/T);let px=p.x+p.w/2,py=p.y+p.h/2;if(wx<0||wx>=WORLD||wy<0||wy>=ROWS||Math.hypot(wx*T+16-px,wy*T+16-py)>120||map[wy][wx])return;map[wy][wx]=8;p.blocks--;sync();say('PLATFORM PLACED')}
function hurt(n){if(p.invuln>0)return;p.hp=Math.max(0,p.hp-n);p.invuln=1.1;say('OUCH · FIND A SPORE TONIC');if(p.hp<=0){p.hp=100;p.x=Math.max(160,p.x-300);p.y=surface[Math.floor(p.x/T)]*T-p.h;p.vx=p.vy=0;say('YOU FOUND YOUR WAY BACK · VITALITY RESTORED')}sync()}
function initEnemies(){for(let x of [430,680,1010,1320,1690,1900,2350,2670,3100,3460]){let tx=Math.floor(x/T);enemies.push({x,y:surface[tx]*T-24,w:25,h:24,hp:3,max:3,vx:0,dir:rng(x)>0.5?1:-1,hit:0,phase:rng(x*2)*6,home:x})}}
function update(dt){let axis=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);if(axis){p.vx=axis*190;p.face=axis}else p.vx*=Math.pow(.001,dt);p.x=clamp(p.x+p.vx*dt,0,WORLD*T-p.w);if(collides(p.x,p.y))p.x-=p.vx*dt;
