ctx.fillStyle='#614a3b';ctx.fillRect(mx-55,my-46,3,44);ctx.fillStyle='#f8c977';ctx.beginPath();ctx.arc(mx-53,my-51,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff3c0';ctx.beginPath();ctx.arc(mx-53,my-51,3,0,Math.PI*2);ctx.fill();
